VALUES ('kindergarten-a1', $chunk${"t":"Im Kindergarten – A1","d":"Der Lernende kann sein Kind bringen und abholen, wichtige Informationen zu Essen, Kleidung, Abholzeit und Tagesform weitergeben.","s":[["Guten Morgen. Ich bringe Leo.","Kind bringen"],["Guten Morgen, Leo!","Begrüßung"],["Die Jacke kommt an die Garderobe.","Ort"],["Bitte zieh deine Hausschuhe an.","Anweisung"],["Leo hat schon gefrühstückt.","Info"],["Er hat heute kein Fieber.","Hinweis korrigiert: kein Fieber"],["Ich hole Leo um 15 Uhr ab.","Zeit nennen"],["Heute holt die Oma ihn ab.","andere Person"],["Die Oma darf Leo abholen.","Erlaubnis"],["Sein Rucksack ist im Fach.","Ort"],["Hier ist eine Ersatzhose.","Mitbringen"],["Guten Nachmittag. Ich hole Leo ab.","Abholung"],["Wie war sein Tag?","Rückfrage"],["Er hat gut gespielt und gegessen.","Rückmeldung"],["Bis morgen. Auf Wiedersehen.","Abschluss"]],"v":[["der Kindergarten","die Kindergärten","Betreuungseinrichtung","Mein Kind geht in den Kindergarten."],["das Kind","die Kinder","betreutes Kind","Ich bringe mein Kind."],["bringen","—","hinbringen","Ich bringe Leo um acht Uhr."],["abholen","—","holen","Ich hole Leo um 15 Uhr ab."],["die Abholzeit","die Abholzeiten","Zeit zum Abholen","Die Abholzeit ist 15 Uhr."],["die Oma","die Omas","Großmutter","Heute holt die Oma ihn ab."],["der Opa","die Opas","Großvater","Der Opa darf ihn abholen."],["die Garderobe","die Garderoben","Ort für Jacken","Die Jacke hängt an der Garderobe."],["die Hausschuhe","—","Schuhe für drinnen","Bitte Hausschuhe anziehen."],["der Rucksack","die Rucksäcke","Tasche","Der Rucksack ist im Fach."],["das Fach","die Fächer","Ablage","Die Ersatzkleidung liegt im Fach."],["die Ersatzhose","die Ersatzhosen","Hose zum Wechseln","Hier ist eine Ersatzhose."],["das Frühstück","—","erste Mahlzeit","Leo hat schon gefrühstückt."],["das Mittagessen","—","Mahlzeit mittags","Das Mittagessen ist um zwölf."],["spielen","—","Spielaktivität","Er hat gut gespielt."],["essen","—","Nahrung aufnehmen","Er hat gut gegessen."],["schlafen","—","ruhen","Er hat eine Stunde geschlafen."],["der Tag","die Tage","Tagesablauf","Wie war sein Tag?"],["gut","—","positiv","Sein Tag war gut."],["dürfen","—","Erlaubnis haben","Die Oma darf ihn abholen."],["heute","—","aktueller Tag","Heute kommt die Oma."],["morgen","—","nächster Tag","Bis morgen."],["um 15 Uhr","—","Zeitangabe","Ich hole ihn um 15 Uhr ab."],["anziehen","—","Kleidung anlegen","Bitte Hausschuhe anziehen."],["bis morgen","—","Abschiedsformel","Bis morgen!"]],"p":["1. Wo hängt die Jacke? Die Jacke hängt an der Garderobe.","2. Wo stehen die Hausschuhe? Die Hausschuhe stehen im Fach.","3. Wo liegt der Rucksack? Der Rucksack liegt im Fach.","4. Wo spielen die Kinder? Die Kinder spielen im Gruppenraum.","5. Wo essen die Kinder? Sie essen am Tisch im Gruppenraum.","6. Wo wartet die Oma? Die Oma wartet am Eingang."],"dgs":[[1,"Mutter","Guten Morgen. Ich bringe Leo.","Kind bringen"],[1,"Pädagogin","Guten Morgen. Wie geht es ihm heute?","Kind bringen"],[1,"Mutter","Gut. Er hat schon gefrühstückt.","Kind bringen"],[1,"Pädagogin","Wann holen Sie ihn ab?","Kind bringen"],[1,"Mutter","Um 15 Uhr.","Kind bringen"],[1,"Pädagogin","Alles klar.","Kind bringen"],[2,"Mutter","Hallo. Ich hole Leo ab.","Kind abholen"],[2,"Pädagogin","Natürlich. Er ist noch im Gruppenraum.","Kind abholen"],[2,"Mutter","Wie war sein Tag?","Kind abholen"],[2,"Pädagogin","Sehr gut. Er hat gespielt und gut gegessen.","Kind abholen"],[2,"Mutter","Danke. Bis morgen.","Kind abholen"],[2,"Pädagogin","Bis morgen.","Kind abholen"]],"gn":[["Trennbare Verben abholen/anziehen","Trennbare Verben teilen sich im Hauptsatz: abholen → Ich hole mein Kind ab.","Bitte zieh deine Hausschuhe an. · Ich hole Leo um 15 Uhr ab. · Heute holt die Oma ihn ab."],["Perfekt mit haben","Mit dem Perfekt spricht man über Vergangenes. Bei vielen Verben: haben + Partizip II.","Leo hat schon gefrühstückt. · Er hat heute kein Fieber. · Er hat gut gespielt und gegessen."],["Possessiv sein/ihr","Possessivformen wie mein/meine und sein/seine zeigen Zugehörigkeit. Pronomen vermeiden Wiederholungen.","Heute holt die Oma ihn ab. · Wie war sein Tag? · Er hat gut gespielt und gegessen."],["Modalverb dürfen","Modalverben wie können, müssen, sollen und dürfen stehen konjugiert; der zweite Infinitiv steht am Satzende.","Was muss ich mitbringen? · Können Sie mir helfen? · Was soll mein Kind machen?"],["W-Fragen wann/wie","W-Fragen beginnen mit einem Fragewort. Danach folgt in der Regel das Verb.","Was brauchen wir? · Wo ist der Raum? · Wann beginnt es?"],["Zeit mit um","Für Uhrzeiten nutzt man meist „um“, für Wochentage/Datum „am“. „bis“ markiert eine Frist.","Er hat heute kein Fieber. · Ich hole Leo um 15 Uhr ab. · Bis morgen. Auf Wiedersehen."],["Ortsangaben in/an","Ortsangaben helfen bei der Orientierung. Typisch sind in, auf, an, neben, vor, hinter und gegenüber.","Die Jacke hängt an der Garderobe. · Die Hausschuhe stehen im Fach. · Der Rucksack liegt im Fach. · Die Kinder spielen im Gruppenraum."]],"q":[["practice","Wer beginnt das Gespräch?","Mutter","Pädagogin","Niemand"],["practice","Welche Aussage kommt im Dialog wirklich vor?","Gut. Er hat schon gefrühstückt.","Wie war sein Tag?","Ich bestelle eine Pizza."],["practice","Welche Aussage gehört zu diesem Dialog?","Wie war sein Tag?","Gut. Er hat schon gefrühstückt.","Der Zug fährt um sieben Uhr."],["practice","Welche Antwort folgt logisch?","Sehr gut. Er hat gespielt und gut gegessen.","Guten Morgen. Ich bringe Leo.","Ich möchte eine Jacke kaufen."],["grammar","Bei trennbaren Verben steht der abgetrennte Teil ...","oft am Satzende","immer direkt nach dem Subjekt","nie im Satz"],["grammar","Welche Form ist korrekt?","Bitte zieh deine Hausschuhe an.","Ich abhole mein Kind.","Ich mein Kind abholen."],["grammar","Welche Form ist korrekt?","Ich hole Leo um 15 Uhr ab.","Ich ausfülle das Formular.","Ich Formular fülle."],["grammar","Welche Aussage enthält ein trennbares Verb?","Bitte zieh deine Hausschuhe an.","Die Schule ist groß.","Deutsch ist gut."],["grammar","Das Perfekt besteht häufig aus ...","haben + Partizip II","sein + Infinitiv immer","nur einem Nomen"],["grammar","Welche Form ist korrekt?","Leo hat schon gefrühstückt.","Er hat gut essen.","Er gut gegessen."],["grammar","Welche Form spricht über Vergangenes?","Er hat heute kein Fieber.","Er schläft morgen.","Schlaf."],["grammar","Welche Form ist vollständig?","Er hat gut gespielt und gegessen.","Ich geschrieben.","Habe Zettel."],["grammar","Welche Form zeigt Zugehörigkeit zur sprechenden Person?","mein/meine","der/die","wo/wann"],["grammar","Welche Form passt zu „Kind“?","mein Kind","meine Kind","meinen Kind"],["grammar","Welche Form passt zu „Tochter“?","meine Tochter","mein Tochter","meinen Tochter"],["grammar","Welche Aussage ist korrekt?","Heute holt die Oma ihn ab.","Mein Kind sein krank.","Meine Kind ist krank."],["grammar","Bei einem Modalverb steht der zweite Infinitiv ...","am Satzende","immer am Anfang","direkt vor dem Subjekt"],["grammar","Welche Form ist richtig?","Was muss ich mitbringen?","Muss ich mitbringen was?","Ich muss was mitbringen muss."],["grammar","Welche Form ist höflich?","Können Sie mir helfen?","Hilf!","Du helfen."],["grammar","Welche Frage passt zum Thema?","Was soll mein Kind machen?","Kann die Farbe rechnen?","Muss der Bus ein Heft sein?"],["grammar","Welches Fragewort fragt nach einem Ort?","Wo","Wann","Was"],["grammar","Welches Fragewort fragt nach einer Zeit?","Wann","Wo","Wer"],["grammar","Welches Fragewort fragt nach einer Sache/Information?","Was","Wo","Wie alt"],["grammar","Welche Frage passt am besten zum Thema?","Was brauchen wir?","Wie teuer ist ein Auto?","Wo ist das Schwimmbad?"],["grammar","Welche zweite Frage passt ebenfalls?","Wo ist der Raum?","Welche Farbe hat das Wetter?","Wie groß ist die Bank?"],["grammar","Welche Präposition passt zu einer Uhrzeit?","um","am","im"],["grammar","Welche Präposition passt zu einem Wochentag?","am","um","aus"],["grammar","Welche Form nennt 